"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["81494"],{57118(e,t,n){n.d(t,{Ay:()=>l,RM:()=>r});var a=n(74848),i=n(28453),s=n(66422);let r=[{value:"Replies",id:"replies",level:3}];function o(e){let t={blockquote:"blockquote",h1:"h1",h3:"h3",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"in-the-face-of-rape-men-and-women-are-absolutely-equal",children:"In the Face of Rape, Men and Women Are Absolutely Equal!"})}),"\n",(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsx)(t.p,{children:"2006/9/27 11:46:11"}),"\n"]}),"\n",(0,a.jsxs)("div",{style:{textAlign:"center"},children:[(0,a.jsx)("img",{src:(0,s.Ay)("/img/essays/rapingequality/1.jpeg")}),(0,a.jsx)("br",{}),(0,a.jsx)("br",{})]}),"\n",(0,a.jsx)(t.p,{children:"Regardless of whether this ID has any interest in raping men, the fact that men can also be raped is still a fact. From this angle, men also need protection. The protection spoken of here most importantly refers to legal protection. The implementation of such legal protection demonstrates, from one angle, the deepening of gender equality \u2014 at least confirming at the legal level that both men and women have the possibility of being raped. On this point, the legal confirmation of gender equality is extremely necessary. A law that only protects women is a shameless law, because such a law takes gender inequality as its premise, and its shamelessness is determined thereby."}),"\n",(0,a.jsx)(t.p,{children:"Those who say men cannot be raped simply haven't grown their brains properly. Back in May, this ID wrote a post, quoted as follows:"}),"\n",(0,a.jsx)(t.p,{children:"\"Just got back from a social engagement. A few words. Today some people came up from the south. After dinner we went to an entertainment establishment. This was a rather special establishment \u2014 'special' meaning that besides the usual female service providers, there were also male service providers. Of course, in such a place, regardless of gender, the most they do is keep you company for singing and drinking. But in such establishments, there are always some people of poor quality. One of the southerners was a local strongman from back home \u2014 probably used to throwing his weight around on his own turf. Came to Beijing and still thought he was on his own turf, shamelessly displaying his wretchedness. This man apparently liked women with large upper dimensions, and picked a Northeastern big sister whose dimensions surpassed even Taiwan's recently hottest such celebrity. He then kept groping this Northeastern big sister. This ID couldn't stand it and threw out a bet: that the Northeastern big sister could overpower and ravish this southern stinking man. The result was an amusing scene on the sofa. Three minutes later, the Northeastern big sister had the southern stinking man pinned beneath her, yanked off his belt, undid his pants, leaving only his underwear. Everyone watching was in stitches. The reason the southern stinking man wasn't fully disarmed was simply that everyone agreed that the smallness of the southern stinking man's lower parts, when compared to the Northeastern big sister's upper grandeur, could only pale in comparison \u2014 and in a public place, things shouldn't go too far. Nevertheless, this at least proves that men can be raped too! This story contains no pornographic content \u2014 it is merely a simple account of true events, and also serves as a warning to all wretched men: being ravished is not something inherently incompatible with manhood!\""}),"\n",(0,a.jsx)(t.p,{children:"Certain lousy men are always proclaiming this theory: that women inherently have the desire to be raped. But a recent incident this ID encountered proves that men likewise inherently possess the desire to be raped \u2014 I won't go into the specifics. On the question of rape, whether in terms of inclination, desire, or possibility, men and women are absolutely equal. This is an obvious conclusion that lousy men refuse to accept. But regardless of whether men accept it, laws related to rape must be amended on the premise of gender equality. Of course, rape and being-raped games purely for physiological needs are outside the scope of the law \u2014 those are simply a form of sexual play and should actually be protected by law, with only one premise: mutual consent!"}),"\n",(0,a.jsx)(t.h3,{id:"replies",children:"Replies"}),"\n",(0,a.jsxs)("div",{class:"blog-comment",children:[(0,a.jsxs)(t.p,{children:[(0,a.jsx)("span",{class:"blog-comment-chan",children:"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n"})," 2006/9/27 12:25:32",(0,a.jsx)("br",{})]}),(0,a.jsx)(t.p,{children:'A Remarkable Document That Doesn\'t Seem Remarkable: Chen Liangyu \u2014 "Top Leaders" Should Regularly Report on Their Integrity'}),(0,a.jsx)(t.p,{children:'Chen Liangyu: "Top Leaders" Should Regularly Report on Their Integrity'}),(0,a.jsx)(t.p,{children:'The Shanghai Municipal Party Committee and Municipal Government held a cadre meeting on strengthening Party conduct and clean governance yesterday afternoon (August 13, 2003) at the Shanghai Exhibition Center. Centered on deepening the study and implementation of the important thought of "Three Represents," with the special topic of upholding governance for the public good and administration for the people, and consciously serving as good servants of the people, the meeting provided Party conduct and clean governance education for cadres at all levels across the city. Chen Liangyu, member of the Political Bureau of the CPC Central Committee and Secretary of the Shanghai Municipal Party Committee, emphasized at the meeting that in accordance with new situations and new requirements, the Party must persist in implementing the principle of the Party managing the Party and governing the Party strictly, continuously deepening the construction of Party conduct and clean governance and the fight against corruption, further improving Party and government conduct, and providing strong and powerful guarantees for achieving Shanghai\'s grand development goals.'}),(0,a.jsx)(t.p,{children:"Chen Liangyu pointed out that the Municipal Party Committee attaches great importance to the construction of Party conduct and clean governance, that all work has been solid and effective, that combating corruption at the source has been forceful, and that Shanghai's Party and government conduct is on the whole healthy and positive."}),(0,a.jsx)(t.p,{children:"Chen Liangyu said that while affirming achievements, a clear head must be maintained, and existing problems and hidden dangers must be given high attention. Leading cadres at all levels must uphold the correct political direction, strictly observe Party political discipline, and be politically reliable. Being politically reliable means firmly establishing correct ideals and beliefs, always being loyal to the Party and the people, loyal to the cause of socialism with Chinese characteristics, and unswervingly implementing the Party's lines, principles, and policies. At any time and under any circumstances, especially when facing complex international political and economic situations, unclear political direction and unsteady political conviction will not only lead to defeat in political struggles but will also make one unable to resist various sugar-coated bullets and lose one's integrity as a Communist. This is a major ideological and political issue that every leading cadre must resolve well."}),(0,a.jsx)(t.p,{children:"Chen Liangyu emphasized that Party organizations and Party member cadres at all levels must further strengthen political discipline. Leading Party member cadres at all levels must resolutely implement the Party's basic theory, basic line, and basic program. They absolutely must not believe on stage while disbelieving off stage. They absolutely must not publicly express or spread among the masses statements that contradict the Party's lines, principles, policies, and various decisions. They absolutely must not listen to or spread political rumors. Discipline inspection and supervision departments at all levels must, in accordance with central requirements, inspect and supervise Party member cadres' compliance with political discipline. Those who listen to and spread rumors must receive criticism and education, and those who repeatedly refuse to correct their behavior and cause malicious impact must be given Party disciplinary sanctions. Propaganda departments and news organizations must place upholding the correct guidance of public opinion as their top priority, fully leverage the main channel role of public opinion, employ various propaganda methods, and proactively and promptly carry out positive reporting to set the record straight. At the same time, they must strictly observe political discipline and propaganda discipline, and absolutely not provide channels for the spread of erroneous views and statements."}),(0,a.jsx)(t.p,{children:"Chen Liangyu emphasized that regarding the issues repeatedly emphasized by the Central Commission for Discipline Inspection concerning the regulation of leading cadres' clean governance behavior, and in light of Shanghai's actual situation, the Municipal Party Committee is reiterating relevant disciplines and requiring all Party member cadres across the city to observe and implement them:"}),(0,a.jsx)(t.p,{children:"Leading cadres must not interfere with the normal conduct of major matters such as land transfer, project contracting, and enterprise restructuring. No one may use written instructions, telephone calls, or other explicit or implicit means to use personal will to interfere with these operations. The already established bidding system must be strictly implemented, and no one may create exceptions. For matters permitted by national regulations that do not yet meet the conditions for bidding, strict procedures must be followed for collective decision-making."}),(0,a.jsx)(t.p,{children:"Leading cadres must not accept cash, securities, or payment vouchers from any unit or individual related to the exercise of their powers, under any name. When buying or renovating houses, buying cars, or when the cadre, spouse, or children go abroad, they must not accept any form of gift from such parties. In recommending and introducing projects, funds, and talent, they must strictly follow laws, regulations, and systems."}),(0,a.jsx)(t.p,{children:"Leading cadres must not use their power to seek private gain for their spouses, children, or staff around them. Leading cadres must make it explicitly clear that spouses, children, and staff around them must not carry out activities under the leader's banner. No organization may grant any privileges to activities carried out under a leader's banner. Whoever violates the rules bears the responsibility."}),(0,a.jsx)(t.p,{children:'Chen Liangyu emphasized that leading cadres at all levels must continuously strengthen the reform of their subjective world, strive to implement "governing for the public good and administering for the people" in their own thoughts and actions, properly handle the relationship between being an official and being a person, between organization and individual, enhance their consciousness of actively accepting supervision from both inside and outside the Party, continuously improve their own cultivation, and truly become servants of the people with high moral character and good official ethics.'}),(0,a.jsx)(t.p,{children:'Chen Liangyu emphasized that the "top leaders" of Party and government teams at all levels must be models in observing the various regulations of the Central Committee and the Municipal Party Committee on clean self-discipline, and consciously accept supervision from superiors, peers, subordinates, and the masses. They must regularly report on their clean governance practices at democratic life meetings and plenary sessions of the Party committee, including information on the employment and education of their spouses and children. Questions reflected in letters and visits from the masses must be truthfully explained to the organization. At least once every six months, they must go to the grassroots level to directly hear the opinions of the masses regarding themselves, their team\'s work, and their clean governance practices. Reported problems and opinions must be promptly rectified, and the rectification status must be publicly disclosed within a certain scope. Chen Liangyu reiterated that he himself would first consciously accept the supervision of the broad masses of Party members and people, ensuring that the power in his hands would never be used to benefit family members and relatives. If anyone conducts business in the name of his family or relatives, they must refuse to see them or handle the matter, and immediately report it.'}),(0,a.jsx)(t.p,{children:"(Source: Morning News, August 14, 2003)"}),(0,a.jsx)(t.p,{children:"__Chen Liangyu Emphasizes Earnestly Safeguarding Party Members' Rights and Advancing Inner-Party Democracy"}),(0,a.jsx)(t.p,{children:"Jiefang Daily (Reporter Dong Qiang): Yesterday morning, the Municipal Party Committee held a standing committee study session, specially studying the \"Regulations on Safeguarding the Rights of Members of the Communist Party of China.\" Comrade Chen Liangyu chaired the meeting and spoke, emphasizing that the \"Regulations on Safeguarding Party Members' Rights\" is an extremely important inner-Party regulation regarding the safeguarding of Party members' rights. Party organizations at all levels across the city and the broad masses of Communist Party members must earnestly study, widely publicize, and strictly observe it. In accordance with the requirements of the Regulations, they must earnestly carry out all work related to safeguarding Party members' rights, continuously advance inner-Party democracy, further improve the Party's governing capacity, fully mobilize the enthusiasm, initiative, and creativity of Party members, and enhance the Party's creativity, cohesion, and combat effectiveness, providing strong political guarantees for Shanghai's reform, opening up, and development."}),(0,a.jsx)(t.p,{children:"Source: Jiefang Daily, November 6, 2004)"}),(0,a.jsx)(t.p,{children:"__Shanghai Municipal Party Secretary Chen Liangyu Emphasizes Joint Party-Government Effort to Implement Anti-Corruption and Clean Governance"}),(0,a.jsx)(t.p,{children:"The national televised and teleconferenced meeting on implementing the Party conduct and clean governance responsibility system was held yesterday afternoon. Chen Liangyu, member of the Political Bureau of the CPC Central Committee and Secretary of the Shanghai Municipal Party Committee, spoke at the Shanghai venue, emphasizing that guided by Deng Xiaoping Theory and the important thought of \"Three Represents,\" and in earnest implementation of the spirit of the Fourth Plenary Session of the 16th CPC Central Committee, standing at the height of strengthening the Party's governing capacity, in accordance with central requirements, the Party must continuously improve and earnestly implement the Party conduct and clean governance responsibility system, strive to form the combined force of the whole Party working on Party conduct, and further open new prospects for Shanghai's Party conduct and clean governance and anti-corruption work."}),(0,a.jsx)(t.p,{children:"Chen Liangyu pointed out that implementing the Party conduct and clean governance responsibility system is a major measure to ensure, from an institutional perspective, that the whole Party works on Party conduct and clean governance construction. Party committees and governments at all levels across the city must persist in joint Party-government effort, strengthen work synergy, and in accordance with the requirements of the responsibility system, assume full leadership responsibility for Party conduct and clean governance construction and anti-corruption work."})]})]})}function l(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(o,{...e})}):o(e)}},73811(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>o,contentTitle:()=>l,toc:()=>c,assets:()=>h});var a=JSON.parse('{"id":"timeline/essays/rapingequality","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/essays/rapingequality.md","sourceDirName":"timeline/essays","slug":"/timeline/essays/rapingequality","permalink":"/en/timeline/essays/rapingequality","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"rapingequality","title":"","hide_table_of_contents":true,"sidebar_label":"Before Rape, Men and Women Are Absolutely Equal! (2006/9/27 11:46:11)"},"sidebar":"timelineSidebar","previous":{"title":"Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n Composition Recording: Piano Sonata No. 1 (Middle School) (2006/9/25 12:20:35)","permalink":"/en/timeline/music/firstpianosonata"},"next":{"title":"A Not-So-Strange Strange Article: Chen Liangyu: \\"Top Leaders\\" Should Regularly Report on Anti-Corruption (2006/9/27 12:41:38)","permalink":"/en/timeline/essays/incorruptgovernment"}}'),i=n(74848),s=n(28453),r=n(57118);let o={id:"rapingequality",title:"",hide_table_of_contents:!0,sidebar_label:"Before Rape, Men and Women Are Absolutely Equal! (2006/9/27 11:46:11)"},l,h={},c=[...r.RM];function d(e){return(0,i.jsx)(r.Ay,{})}function u(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>r,x:()=>o});var a=n(96540);let i={},s=a.createContext(i);function r(e){let t=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),a.createElement(s.Provider,{value:t},e.children)}}}]);